command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="700500d92442f25002fb707031d7c2ff2cb2052f"
$candidate="56a6ea69c820f2e0bca782525238242baaba0187"
$branch="work/shell-provider-copyout-20261007"
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "provider copyout r3 fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved before provider copyout r3"}
if((& git rev-parse ("refs/remotes/origin/"+$branch)).Trim() -ne $candidate){throw "provider copyout r3 candidate mismatch"}
$dirty=@(& git status --porcelain=v1 -uall)
if($dirty.Count -ne 0){$dirty|%{Write-Host ("UNEXPECTED_WORKTREE="+$_)};throw "persistent checkout dirty"}
& git switch --detach $candidate
if($LASTEXITCODE -ne 0){throw "provider copyout r3 checkout failed"}
& .\build.bat Release
if($LASTEXITCODE -ne 0){throw "provider copyout r3 Release build failed"}
& python -X utf8 tests\winui\test_shell_provider_copyout_gui.py --configuration Release
if($LASTEXITCODE -ne 0){throw "provider copyout r3 focused GUI failed"}
& git switch main
if($LASTEXITCODE -ne 0){throw "failed to restore main after provider copyout r3"}
& git merge --ff-only origin/main
if($LASTEXITCODE -ne 0){throw "failed to fast-forward main after provider copyout r3"}
Write-Host "SHELL_PROVIDER_COPYOUT_VALIDATION=PASS"
